<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();$id=(int)$u['id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['act']??'';if($act==='cancel'){$q=db()->prepare("UPDATE study_sessions SET status='cancelled' WHERE id=? AND created_by=?");$q->execute([(int)$_POST['id'],$id]);flash('success','Session cancelled.');go('sessions.php');}if($act==='create'){$title=trim($_POST['title']??'');$date=$_POST['date']??'';$start=$_POST['start_time']??'';$end=$_POST['end_time']??'';$mode=$_POST['mode']??'Online';if(!$title||!strtotime($date)||$date<date('Y-m-d')||!preg_match('/^\d{2}:\d{2}$/',$start)||!preg_match('/^\d{2}:\d{2}$/',$end)||$start>=$end){flash('danger','Enter a valid title, future date, and end time after start time.');go('sessions.php');}$group=(int)($_POST['group_id']??0)?:null;$partner=(int)($_POST['partner_id']??0)?:null;if($group){$q=db()->prepare('SELECT COUNT(*) FROM group_members WHERE group_id=? AND user_id=?');$q->execute([$group,$id]);if(!$q->fetchColumn())$group=null;}if($partner){$q=db()->prepare("SELECT COUNT(*) FROM study_requests WHERE status='accepted' AND ((sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?))");$q->execute([$id,$partner,$partner,$id]);if(!$q->fetchColumn())$partner=null;}db()->prepare('INSERT INTO study_sessions(title,subject,session_date,start_time,end_time,mode,meeting_link,notes,group_id,partner_id,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$title,trim($_POST['subject']??''),$date,$start,$end,$mode,trim($_POST['meeting_link']??''),trim($_POST['notes']??''),$group,$partner,$id]);if($partner)notify($partner,$u['name'].' scheduled a study session.','sessions.php');flash('success','Study session scheduled.');go('sessions.php');}}$q=db()->prepare("SELECT DISTINCT s.*,g.name group_name,p.name partner_name FROM study_sessions s LEFT JOIN study_groups g ON g.id=s.group_id LEFT JOIN users p ON p.id=s.partner_id WHERE (s.created_by=? OR s.partner_id=? OR s.group_id IN (SELECT group_id FROM group_members WHERE user_id=?)) AND s.status='scheduled' ORDER BY s.session_date,s.start_time");$q->execute([$id,$id,$id]);$rows=$q->fetchAll();$groups=db()->prepare('SELECT g.id,g.name FROM group_members m JOIN study_groups g ON g.id=m.group_id WHERE m.user_id=?');$groups->execute([$id]);$connections=db()->prepare("SELECT DISTINCT u.id,u.name FROM users u JOIN study_requests r ON r.status='accepted' AND ((r.sender_id=? AND r.receiver_id=u.id) OR (r.receiver_id=? AND r.sender_id=u.id))");$connections->execute([$id,$id]);page_start('Study sessions'); ?><div class="row g-4"><div class="col-lg-8"><div class="card"><div class="card-body"><h2 class="h5 fw-bold">Upcoming sessions</h2><?php foreach($rows as $s): ?><div class="d-flex justify-content-between border-top py-3"><div><strong><?= e($s['title']) ?></strong><div class="small text-secondary"><?= e($s['subject']) ?> · <?= e($s['group_name']?:$s['partner_name']?:$s['mode']) ?> · <?= e(substr($s['start_time'],0,5)) ?>–<?= e(substr($s['end_time'],0,5)) ?></div><?php if($s['meeting_link']): ?><a class="small" href="<?= e($s['meeting_link']) ?>" target="_blank" rel="noopener">Open meeting link</a><?php endif ?></div><div class="text-end small"><?= e($s['session_date']) ?><?php if((int)$s['created_by']===$id): ?><form method="post" class="mt-2"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="act" value="cancel"><input type="hidden" name="id" value="<?= $s['id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Cancel this session?">Cancel</button></form><?php endif ?></div></div><?php endforeach ?><?php if(!$rows): ?><div class="empty">No upcoming sessions. Plan a focused study block below.</div><?php endif ?></div></div></div><div class="col-lg-4"><div class="card"><div class="card-body"><h2 class="h5 fw-bold">Schedule session</h2><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="act" value="create"><label class="form-label">Title</label><input class="form-control mb-2" name="title" required><label class="form-label">Subject</label><input class="form-control mb-2" name="subject"><label class="form-label">Date</label><input class="form-control mb-2" type="date" min="<?= date('Y-m-d') ?>" name="date" required><div class="row"><div class="col"><label class="form-label">Start</label><input class="form-control mb-2" type="time" name="start_time" required></div><div class="col"><label class="form-label">End</label><input class="form-control mb-2" type="time" name="end_time" required></div></div><label class="form-label">Mode</label><select class="form-select mb-2" name="mode"><option>Online</option><option>Offline</option><option>Both</option></select><label class="form-label">Group</label><select class="form-select mb-2" name="group_id"><option value="">None</option><?php foreach($groups as $g): ?><option value="<?= $g['id'] ?>"><?= e($g['name']) ?></option><?php endforeach ?></select><label class="form-label">Partner</label><select class="form-select mb-2" name="partner_id"><option value="">None</option><?php foreach($connections as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach ?></select><input class="form-control mb-2" name="meeting_link" placeholder="Meeting link (optional)"><textarea class="form-control mb-3" name="notes" placeholder="Notes"></textarea><button class="btn btn-primary w-100">Schedule</button></form></div></div></div></div><?php page_end(); ?>
